<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>PipeBill: Invoicing Built for Plumbers</title>
  <meta name="description" content="Create professional invoices on the job, get paid faster, and spend less time on paperwork. Invoicing made for plumbers.">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      color: #1f2937;
      line-height: 1.6;
      background: #ffffff;
    }
    a { color: inherit; text-decoration: none; }
    .container { max-width: 1100px; margin: 0 auto; padding: 0 24px; }

    /* Nav */
    nav {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 20px 0;
    }
    .logo { font-weight: 800; font-size: 1.4rem; color: #0b5cad; }
    .nav-links a { margin-left: 28px; font-weight: 500; color: #4b5563; }
    .btn {
      display: inline-block;
      padding: 14px 28px;
      border-radius: 8px;
      font-weight: 600;
      font-size: 1rem;
      transition: transform 0.15s, box-shadow 0.15s;
    }
    .btn:hover { transform: translateY(-1px); }
    .btn-primary { background: #e8590c; color: #fff; box-shadow: 0 4px 14px rgba(232,89,12,0.35); }
    .btn-secondary { background: #f3f4f6; color: #1f2937; margin-left: 12px; }

    /* Hero */
    .hero { padding: 80px 0 100px; background: linear-gradient(180deg, #eef6ff 0%, #ffffff 100%); }
    .hero-grid { display: grid; grid-template-columns: 1.1fr 1fr; gap: 60px; align-items: center; }
    .eyebrow {
      display: inline-block;
      background: #dbeafe;
      color: #0b5cad;
      padding: 6px 14px;
      border-radius: 999px;
      font-size: 0.85rem;
      font-weight: 600;
      margin-bottom: 20px;
    }
    h1 { font-size: 3.2rem; line-height: 1.1; letter-spacing: -0.02em; margin-bottom: 20px; }
    h1 span { color: #0b5cad; }
    .hero p.lead { font-size: 1.2rem; color: #4b5563; margin-bottom: 32px; max-width: 520px; }
    .hero-note { margin-top: 16px; font-size: 0.9rem; color: #6b7280; }

    .invoice-card {
      background: #fff;
      border-radius: 16px;
      box-shadow: 0 20px 60px rgba(11,92,173,0.15);
      padding: 32px;
      border: 1px solid #e5e7eb;
    }
    .invoice-card h3 { font-size: 1rem; color: #6b7280; font-weight: 500; margin-bottom: 4px; }
    .invoice-card .total { font-size: 2.2rem; font-weight: 800; margin-bottom: 20px; }
    .line { display: flex; justify-content: space-between; padding: 10px 0; border-bottom: 1px solid #f3f4f6; font-size: 0.95rem; }
    .status {
      margin-top: 20px;
      background: #d1fae5;
      color: #065f46;
      padding: 10px 14px;
      border-radius: 8px;
      font-weight: 600;
      text-align: center;
    }

    /* Sections */
    section { padding: 90px 0; }
    .section-title { text-align: center; margin-bottom: 56px; }
    .section-title h2 { font-size: 2.4rem; letter-spacing: -0.01em; margin-bottom: 12px; }
    .section-title p { color: #6b7280; font-size: 1.1rem; max-width: 600px; margin: 0 auto; }

    .features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
    .feature {
      padding: 32px;
      border: 1px solid #e5e7eb;
      border-radius: 14px;
      transition: box-shadow 0.2s;
    }
    .feature:hover { box-shadow: 0 10px 30px rgba(0,0,0,0.06); }
    .icon {
      width: 48px; height: 48px;
      background: #fff4ed;
      border-radius: 12px;
      display: flex; align-items: center; justify-content: center;
      font-size: 1.5rem;
      margin-bottom: 18px;
    }
    .feature h3 { font-size: 1.2rem; margin-bottom: 8px; }
    .feature p { color: #6b7280; font-size: 0.97rem; }

    /* How it works */
    .steps-bg { background: #f9fafb; }
    .steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; text-align: center; }
    .step-num {
      width: 56px; height: 56px;
      border-radius: 50%;
      background: #0b5cad;
      color: #fff;
      font-weight: 700;
      font-size: 1.3rem;
      display: flex; align-items: center; justify-content: center;
      margin: 0 auto 18px;
    }
    .step h3 { margin-bottom: 8px; font-size: 1.2rem; }
    .step p { color: #6b7280; }

    /* Pricing */
    .pricing { display: grid; grid-template-columns: repeat(2, 1fr); gap: 28px; max-width: 800px; margin: 0 auto; }
    .plan { border: 1px solid #e5e7eb; border-radius: 16px; padding: 40px; }
    .plan.featured { border: 2px solid #e8590c; position: relative; }
    .plan .badge {
      position: absolute; top: -14px; left: 40px;
      background: #e8590c; color: #fff;
      padding: 4px 12px; border-radius: 999px;
      font-size: 0.8rem; font-weight: 600;
    }
    .plan h3 { font-size: 1.3rem; margin-bottom: 6px; }
    .price { font-size: 2.6rem; font-weight: 800; margin: 16px 0; }
    .price small { font-size: 1rem; color: #6b7280; font-weight: 500; }
    .plan ul { list-style: none; margin: 24px 0 32px; }
    .plan li { padding: 8px 0; color: #374151; }
    .plan li::before { content: "✓ "; color: #059669; font-weight: 700; }
    .plan .btn { width: 100%; text-align: center; }

    /* Testimonial */
    .testimonial { text-align: center; max-width: 720px; margin: 0 auto; }
    .testimonial blockquote { font-size: 1.4rem; font-style: italic; color: #374151; margin-bottom: 20px; }
    .testimonial cite { font-style: normal; font-weight: 600; color: #1f2937; }
    .testimonial span { color: #6b7280; display: block; font-size: 0.95rem; }

    /* Final CTA */
    .cta {
      background: #0b5cad;
      color: #fff;
      text-align: center;
      border-radius: 24px;
      padding: 80px 40px;
    }
    .cta h2 { font-size: 2.6rem; margin-bottom: 16px; }
    .cta p { font-size: 1.15rem; opacity: 0.9; margin-bottom: 32px; }
    .cta .btn-primary { font-size: 1.1rem; padding: 16px 34px; }

    footer { padding: 40px 0; text-align: center; color: #6b7280; font-size: 0.9rem; border-top: 1px solid #e5e7eb; margin-top: 60px; }

    /* Responsive */
    @media (max-width: 860px) {
      .hero-grid, .features, .steps, .pricing { grid-template-columns: 1fr; }
      h1 { font-size: 2.4rem; }
      .nav-links { display: none; }
      .section-title h2, .cta h2 { font-size: 2rem; }
    }
  </style>
</head>
<body>

  <header class="container">
    <nav>
      <div class="logo">PipeBill</div>
      <div class="nav-links">
        <a href="#features">Features</a>
        <a href="#how">How it works</a>
        <a href="#pricing">Pricing</a>
      </div>
      <a href="#signup" class="btn btn-primary" style="padding: 10px 20px;">Start free trial</a>
    </nav>
  </header>

  <main>
    <!-- Hero -->
    <div class="hero">
      <div class="container hero-grid">
        <div>
          <span class="eyebrow">Built for plumbers, by people who know the trade</span>
          <h1>Invoice from the <span>crawl space</span> to the bank in minutes.</h1>
          <p class="lead">PipeBill lets you create professional invoices on your phone right after the job is done, so you get paid faster and spend your evenings with your family, not your paperwork.</p>
          <a href="#signup" class="btn btn-primary">Start your 30-day free trial</a>
          <a href="#how" class="btn btn-secondary">See how it works</a>
          <p class="hero-note">No credit card required. Cancel anytime.</p>
        </div>
        <div class="invoice-card">
          <h3>Invoice #1048 · Drain Repair</h3>
          <div class="total">$485.00</div>
          <div class="line"><span>Snake main sewer line</span><span>$225.00</span></div>
          <div class="line"><span>Replace PVC cleanout cap</span><span>$40.00</span></div>
          <div class="line"><span>Parts (3/4" fittings)</span><span>$68.00</span></div>
          <div class="line"><span>Labor, 2.5 hrs</span><span>$152.00</span></div>
          <div class="status">Paid via text link · Just now</div>
        </div>
      </div>
    </div>

    <!-- Features -->
    <section id="features">
      <div class="container">
        <div class="section-title">
          <h2>Everything you need to get paid, nothing you don't</h2>
          <p>Stop scribbling on carbon copies and chasing checks. PipeBill is simple enough to use with dirty hands.</p>
        </div>
        <div class="features">
          <div class="feature">
            <div class="icon">📱</div>
            <h3>Invoice on site</h3>
            <p>Build and send invoices from your phone before you leave the driveway. Use saved line items for common jobs like water heater swaps and toilet repairs.</p>
          </div>
          <div class="feature">
            <div class="icon">💳</div>
            <h3>Get paid faster</h3>
            <p>Customers pay by card, bank transfer, or Apple Pay from a link in a text message. Automatic reminders keep overdue invoices from slipping through the cracks.</p>
          </div>
          <div class="feature">
            <div class="icon">🧾</div>
            <h3>Track parts and labor</h3>
            <p>Add materials, markup, and labor hours in seconds. Every invoice shows exactly what the customer paid for, with clean line items they can understand.</p>
          </div>
          <div class="feature">
            <div class="icon">🛠️</div>
            <h3>Emergency-call ready</h3>
            <p>Set after-hours and emergency rates once and apply them with a single tap. No more guessing what to charge at 2 a.m.</p>
          </div>
          <div class="feature">
            <div class="icon">📊</div>
            <h3>Know where your money is</h3>
            <p>See what's paid, what's outstanding, and what's overdue at a glance. Export everything for your accountant at tax time.</p>
          </div>
          <div class="feature">
            <div class="icon">🔒</div>
            <h3>Your records, secure</h3>
            <p>Customer details and payment information are encrypted and backed up automatically. Your invoice history is always there when you need it.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- How it works -->
    <section id="how" class="steps-bg">
      <div class="container">
        <div class="section-title">
          <h2>From job to paid in three steps</h2>
          <p>Set up in about ten minutes. Then invoicing takes less time than writing the job notes.</p>
        </div>
        <div class="steps">
          <div class="step">
            <div class="step-num">1</div>
            <h3>Add your jobs</h3>
            <p>Pick saved services, add parts and hours, and snap a photo of the work if you want a record.</p>
          </div>
          <div class="step">
            <div class="step-num">2</div>
            <h3>Send it instantly</h3>
            <p>Text or email the invoice to your customer before you pack up the van. They can review it right away.</p>
          </div>
          <div class="step">
            <div class="step-num">3</div>
            <h3>Get paid</h3>
            <p>Customers tap to pay online. You get notified when the money lands, and PipeBill handles the follow-ups.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Testimonial -->
    <section>
      <div class="container testimonial">
        <blockquote>"I used to spend Sunday nights chasing invoices from the week. Now they go out from the job site and most get paid before I've driven home. It's the best tool I've put on my phone."</blockquote>
        <cite>Mike Turner</cite>
        <span>Owner, Turner Plumbing & Heating</span>
      </div>
    </section>

    <!-- Pricing -->
    <section id="pricing" class="steps-bg">
      <div class="container">
        <div class="section-title">
          <h2>Simple pricing for independent plumbers</h2>
          <p>No contracts, no hidden fees. Start free and upgrade when you're ready.</p>
        </div>
        <div class="pricing">
          <div class="plan">
            <h3>Solo</h3>
            <div class="price">$19 <small>/ month</small></div>
            <p>For owner-operators running their own trucks.</p>
            <ul>
              <li>Unlimited invoices</li>
              <li>Online card and bank payments</li>
              <li>Automatic payment reminders</li>
              <li>Saved line items and rate sheets</li>
              <li>Mobile app access</li>
            </ul>
            <a href="#signup" class="btn btn-secondary">Start free trial</a>
          </div>
          <div class="plan featured">
            <span class="badge">Most popular</span>
            <h3>Crew</h3>
            <div class="price">$49 <small>/ month</small></div>
            <p>For shops with technicians and office staff.</p>
            <ul>
              <li>Everything in Solo</li>
              <li>Up to 5 team members</li>
              <li>Job photos and notes</li>
              <li>Accounting exports (QuickBooks, Xero)</li>
              <li>Priority support</li>
            </ul>
            <a href="#signup" class="btn btn-primary">Start free trial</a>
          </div>
        </div>
      </div>
    </section>

    <!-- Final CTA -->
    <section id="signup">
      <div class="container">
        <div class="cta">
          <h2>Stop doing paperwork at the kitchen table.</h2>
          <p>Join thousands of plumbers who invoice faster and get paid sooner. Your first 30 days are on us.</p>
          <a href="#" class="btn btn-primary">Start your free trial</a>
          <p style="margin-top: 16px; font-size: 0.95rem; margin-bottom: 0;">No credit card required.</p>
        </div>
      </div>
    </section>
  </main>

  <footer>
    <div class="container">
      <p>&copy; 2026 PipeBill. Invoicing for the trades.</p>
      <p style="margin-top: 8px;">
        <a href="#">Privacy</a> &nbsp;·&nbsp; <a href="#">Terms</a> &nbsp;·&nbsp; <a href="#">Support</a>
      </p>
    </div>
  </footer>

</body>
</html>
```
